ALTER TABLE public.shop_quizzes ADD COLUMN reward_kind text NOT NULL DEFAULT 'spins' CHECK(reward_kind IN ('spins','voucher','code')), ADD COLUMN reward_voucher_code text;
CREATE TABLE public.shop_quiz_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_id uuid NOT NULL REFERENCES public.shop_quizzes(id),content text NOT NULL CHECK(length(content) BETWEEN 1 AND 4000),awarded_to uuid,awarded_at timestamptz,UNIQUE(quiz_id,content));
GRANT ALL ON public.shop_quiz_codes TO service_role; ALTER TABLE public.shop_quiz_codes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.shop_quiz_rewards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_id uuid NOT NULL REFERENCES public.shop_quizzes(id),shop_id uuid NOT NULL REFERENCES public.shops(id),user_id uuid NOT NULL,kind text NOT NULL,points integer NOT NULL,entries integer NOT NULL DEFAULT 0,delivered_content text,telegram_state text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,quiz_id));
GRANT SELECT ON public.shop_quiz_rewards TO authenticated; GRANT ALL ON public.shop_quiz_rewards TO service_role; ALTER TABLE public.shop_quiz_rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own quiz rewards" ON public.shop_quiz_rewards FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM shops s WHERE s.id=shop_id AND s.owner_id=auth.uid()));
CREATE FUNCTION public.configure_quiz_reward(_actor uuid,_quiz uuid,_kind text,_voucher text,_codes text[]) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q shop_quizzes; n integer:=0; BEGIN SELECT * INTO q FROM shop_quizzes WHERE id=_quiz FOR UPDATE; IF q.id IS NULL OR (NOT public.has_role(_actor,'admin') AND NOT EXISTS(SELECT 1 FROM shops WHERE id=q.shop_id AND owner_id=_actor)) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _kind NOT IN ('spins','voucher','code') THEN RAISE EXCEPTION 'Invalid reward'; END IF; IF _kind='voucher' AND NOT EXISTS(SELECT 1 FROM vouchers WHERE shop_id=q.shop_id AND code=_voucher AND is_active) THEN RAISE EXCEPTION 'Voucher not found in shop'; END IF; UPDATE shop_quizzes SET reward_kind=_kind,reward_voucher_code=CASE WHEN _kind='voucher' THEN _voucher END WHERE id=_quiz; IF _kind='code' THEN INSERT INTO shop_quiz_codes(quiz_id,content) SELECT _quiz,trim(c) FROM unnest(coalesce(_codes,'{}')) c WHERE length(trim(c))>0 ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; END IF; RETURN n; END $$;
CREATE FUNCTION public.play_shop_quiz_reward(_user uuid,_quiz uuid,_answer integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q shop_quizzes; c growth_campaigns; code_row shop_quiz_codes; content text; ent integer:=0; rid uuid; BEGIN SELECT * INTO q FROM shop_quizzes WHERE id=_quiz FOR UPDATE; SELECT * INTO c FROM growth_campaigns WHERE id=q.campaign_id FOR UPDATE; IF c.id IS NULL OR c.status<>'active' OR now()<c.starts_at OR now()>=c.ends_at THEN RAISE EXCEPTION 'Campaign not open'; END IF; IF NOT EXISTS(SELECT 1 FROM growth_members WHERE campaign_id=c.id AND user_id=_user) THEN RAISE EXCEPTION 'Join campaign first'; END IF; IF EXISTS(SELECT 1 FROM shop_points WHERE quiz_id=_quiz AND user_id=_user) THEN RAISE EXCEPTION 'Already rewarded'; END IF; IF NOT EXISTS(SELECT 1 FROM shop_quiz_answers WHERE quiz_id=_quiz AND correct_index=_answer) THEN RAISE EXCEPTION 'Incorrect answer'; END IF;
 IF q.reward_kind='code' THEN SELECT * INTO code_row FROM shop_quiz_codes WHERE quiz_id=_quiz AND awarded_to IS NULL ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED; IF code_row.id IS NULL THEN RAISE EXCEPTION 'Rewards sold out'; END IF; UPDATE shop_quiz_codes SET awarded_to=_user,awarded_at=now() WHERE id=code_row.id; content:=code_row.content;
 ELSIF q.reward_kind='voucher' THEN content:=q.reward_voucher_code;
 ELSE ent:=q.entries; UPDATE growth_members SET entries=least(c.max_entries,entries+q.entries) WHERE campaign_id=c.id AND user_id=_user; END IF;
 INSERT INTO shop_points(shop_id,user_id,quiz_id,amount) VALUES(q.shop_id,_user,q.id,q.points);
 INSERT INTO shop_quiz_rewards(quiz_id,shop_id,user_id,kind,points,entries,delivered_content,telegram_state) VALUES(q.id,q.shop_id,_user,q.reward_kind,q.points,ent,content,CASE WHEN content IS NULL THEN 'none' ELSE 'pending' END) RETURNING id INTO rid;
 INSERT INTO growth_events(campaign_id,actor_id,event) VALUES(c.id,_user,'quiz_reward');
 RETURN jsonb_build_object('id',rid,'kind',q.reward_kind,'points',q.points,'entries',ent,'content',content); END $$;
REVOKE ALL ON FUNCTION public.configure_quiz_reward(uuid,uuid,text,text,text[]),public.play_shop_quiz_reward(uuid,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.configure_quiz_reward(uuid,uuid,text,text,text[]),public.play_shop_quiz_reward(uuid,uuid,integer) TO service_role;